'use strict';
const { chromium } = require('playwright');
const ORIGIN = process.env.FORMATX_TEST_URL || 'https://formatxsuite.com/';
const CASES=[['320x568',320,568,true],['360x800',360,800,true],['375x812',375,812,true],['390x844',390,844,true],['412x915',412,915,true],['phone-landscape',844,390,true],['tablet',768,1024,true],['1080p',1920,1080,false],['1440p',2560,1440,false],['ultrawide',3440,1440,false],['4k',3840,2160,false]];
function ok(v,m){if(!v)throw new Error(m)}
function wire(p,e,f){p.on('pageerror',x=>e.push(`pageerror:${x}`));p.on('console',m=>{if(m.type()==='error')e.push(`console:${m.text()}`)});p.on('requestfailed',r=>f.push(`${r.method()} ${r.url()} ${r.failure()?.errorText||''}`));p.on('response',r=>{try{const u=new URL(r.url());if(u.hostname.endsWith('formatxsuite.com')&&r.status()>=400)f.push(`${r.status()} ${r.url()}`)}catch{}})}
async function inspect(p){return p.evaluate(()=>{const q=s=>document.querySelector(s),vis=e=>e&&getComputedStyle(e).display!=='none'&&getComputedStyle(e).visibility!=='hidden'&&e.getBoundingClientRect().width>0;const small=[...document.querySelectorAll('a,button,input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(vis).map(e=>{const r=e.getBoundingClientRect();return{tag:e.tagName,id:e.id,t:(e.textContent||e.getAttribute('aria-label')||'').trim().slice(0,32),w:r.width,h:r.height}}).filter(x=>x.w<40||x.h<40).slice(0,20);return{overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth,h1:document.querySelectorAll('h1').length,main:!!q('main'),header:!!q('header'),nav:!!q('nav'),footer:!!q('footer'),skip:!!q('a.skip-link[href^="#"]'),lang:document.documentElement.lang,title:document.title,desc:!!q('meta[name="description"]'),canonical:q('link[rel="canonical"]')?.href||'',hero:!!q('#hero'),mag:!!q('.fx-reference-mag-button,.fx-apex-canvas,[data-fx-core],canvas'),live:!!q('#live-os,[data-fx-live-os],a[href*="live-os"]'),proof:!!q('[data-fx-award-proof],.fx-proof-grid'),small}})}
async function one(b,[name,width,height,touch]){const c=await b.newContext({viewport:{width,height},locale:'hu-HU',colorScheme:'dark',hasTouch:touch,isMobile:touch&&width<900});const p=await c.newPage(),e=[],f=[];wire(p,e,f);await p.goto(`${ORIGIN}${ORIGIN.includes('?')?'&':'?'}p0_browser=${name}-${Date.now()}`,{waitUntil:'domcontentloaded',timeout:60000});await p.waitForTimeout(1800);const d=await inspect(p);ok(!e.length,`${name}: errors ${e.join(' | ')}`);ok(!f.length,`${name}: broken resources ${f.join(' | ')}`);ok(d.overflow<=2,`${name}: overflow ${d.overflow}`);ok(d.h1===1&&d.main&&d.header&&d.nav&&d.footer&&d.skip,`${name}: semantic shell failed ${JSON.stringify(d)}`);ok((d.lang==='hu'||d.lang==='en')&&d.title&&d.desc&&d.canonical.startsWith('https://formatxsuite.com'),`${name}: SEO shell failed`);ok(d.hero&&d.mag&&d.live&&d.proof,`${name}: product layer missing`);if(touch)ok(!d.small.length,`${name}: touch targets ${JSON.stringify(d.small)}`);await p.keyboard.press('Tab');ok(await p.evaluate(()=>document.activeElement&&document.activeElement!==document.body),`${name}: keyboard focus failed`);console.log(JSON.stringify({case:name,pass:true,data:d}));await c.close()}
async function reduced(b){const c=await b.newContext({viewport:{width:390,height:844},reducedMotion:'reduce',hasTouch:true,isMobile:true});const p=await c.newPage(),e=[],f=[];wire(p,e,f);await p.goto(`${ORIGIN}?p0_reduced=1`,{waitUntil:'domcontentloaded'});await p.waitForTimeout(1000);const d=await inspect(p);ok(!e.length&&!f.length&&d.overflow<=2&&d.hero&&d.proof,'reduced-motion failed');await c.close()}
async function nojs(b){const c=await b.newContext({viewport:{width:390,height:844},javaScriptEnabled:false});const p=await c.newPage();await p.goto(ORIGIN,{waitUntil:'domcontentloaded'});const d=await p.evaluate(()=>({text:(document.body.innerText||'').length,h1:document.querySelectorAll('h1').length,main:!!document.querySelector('main'),proof:/Bizonyíték|Proof/i.test(document.body.innerText||''),overflow:document.documentElement.scrollWidth-innerWidth}));ok(d.text>1200&&d.h1===1&&d.main&&d.proof&&d.overflow<=2,`no-JS failed ${JSON.stringify(d)}`);await c.close()}
async function noWebgl(b){const c=await b.newContext({viewport:{width:390,height:844},hasTouch:true,isMobile:true});await c.addInitScript(()=>{const o=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(t,...a){if(t==='webgl'||t==='webgl2'||t==='experimental-webgl')return null;return o.call(this,t,...a)}});const p=await c.newPage(),e=[],f=[];wire(p,e,f);await p.goto(`${ORIGIN}?p0_no_webgl=1`,{waitUntil:'domcontentloaded'});await p.waitForTimeout(1600);const d=await inspect(p);ok(!e.length,`WebGL fallback errors ${e}`);ok(!f.length&&d.hero&&d.live&&d.proof&&d.overflow<=2,'WebGL fallback unusable');await c.close()}
(async()=>{const b=await chromium.launch({headless:true,args:['--enable-unsafe-swiftshader','--disable-dev-shm-usage']});try{for(const x of CASES)await one(b,x);await reduced(b);await nojs(b);await noWebgl(b);console.log('P0_BROWSER_MATRIX_PASS')}finally{await b.close()}})().catch(e=>{console.error(e.stack||e);process.exit(1)});
